mapper.select:
SELECT e.* FROM edu_exam e


        AND e.exam_paper_id = #{query.examPaperId}


        AND e.exam_name LIKE CONCAT('%', #{query.examName}, '%')


        AND e.exam_class_id = #{query.examClassId}


        AND e.exam_status = #{query.examStatus}



            AND (e.exam_owner_user_id IS NULL OR e.exam_owner_user_id = #{scope.ownerPredicate})



ORDER BY e.create_time DESC
